/**
 * "Join the Circle" Interactive Modal Component
 * Lets users create their custom 3D dancer avatar and join the spinning Garba ring
 */

import confetti from 'canvas-confetti';

export class JoinModal {
  constructor({ onJoinSuccess }) {
    this.onJoinSuccess = onJoinSuccess;
    this.isOpen = false;
    this.el = null;
    this.build();
  }

  build() {
    this.el = document.createElement('div');
    this.el.className = 'join-modal';
    this.el.id = 'join-modal';
    this.el.setAttribute('role', 'dialog');
    this.el.setAttribute('aria-modal', 'true');
    this.el.setAttribute('aria-hidden', 'true');

    this.el.innerHTML = `
      <div class="modal-backdrop"></div>
      <div class="modal-card">
        <button class="modal-close-btn" id="join-close">✕</button>
        <div class="modal-header">
          <span class="modal-badge">&#128131; Garba Gang Waiting!</span>
          <h2 class="modal-title">ગરબે ઘૂમો Join The 3D Circle</h2>
          <p class="modal-subtitle">Customize your traditional Gujarati Khelaiya avatar and step into the 3D ground!</p>
        </div>

        <form class="join-form" id="join-form">
          <div class="form-group">
            <label for="dancer-name">તમારું નામ Your Name</label>
            <input type="text" id="dancer-name" required placeholder="e.g. Radhika, Keshav, Jignesh..." maxlength="24" />
          </div>

          <div class="form-group">
            <label>Costume Style પોશાક</label>
            <div class="gender-toggle">
              <label class="radio-label">
                <input type="radio" name="gender" value="female" checked />
                <span class="custom-radio">Chaniya Choli (ચણિયા ચોળી)</span>
              </label>
              <label class="radio-label">
                <input type="radio" name="gender" value="male" />
                <span class="custom-radio">Kediyu & Dhoti (કેડિયું)</span>
              </label>
            </div>
          </div>

          <div class="form-group">
            <label>Cloth Color Theme રંગ</label>
            <div class="color-options">
              <label class="color-chip" style="--c: #C4245A;" title="Rani Pink & Gold">
                <input type="radio" name="clothColor" value="#C4245A" checked />
                <span class="color-swatch"></span>
              </label>
              <label class="color-chip" style="--c: #0E3B32;" title="Peacock Emerald">
                <input type="radio" name="clothColor" value="#0E3B32" />
                <span class="color-swatch"></span>
              </label>
              <label class="color-chip" style="--c: #7A1522;" title="Kutchi Red">
                <input type="radio" name="clothColor" value="#7A1522" />
                <span class="color-swatch"></span>
              </label>
              <label class="color-chip" style="--c: #4A1180;" title="Royal Violet">
                <input type="radio" name="clothColor" value="#4A1180" />
                <span class="color-swatch"></span>
              </label>
              <label class="color-chip" style="--c: #1B3A5C;" title="Patan Patola Indigo">
                <input type="radio" name="clothColor" value="#1B3A5C" />
                <span class="color-swatch"></span>
              </label>
              <label class="color-chip" style="--c: #E8A838;" title="Turmeric Saffron">
                <input type="radio" name="clothColor" value="#E8A838" />
                <span class="color-swatch"></span>
              </label>
            </div>
          </div>

          <div class="form-group">
            <label>Dandiya Glow Color દાંડિયા</label>
            <div class="color-options">
              <label class="color-chip" style="--c: #FFD700;" title="Golden Brass">
                <input type="radio" name="dandiyaColor" value="#FFD700" checked />
                <span class="color-swatch"></span>
              </label>
              <label class="color-chip" style="--c: #00E5FF;" title="Electric Cyan">
                <input type="radio" name="dandiyaColor" value="#00E5FF" />
                <span class="color-swatch"></span>
              </label>
              <label class="color-chip" style="--c: #FF2D87;" title="Neon Pink">
                <input type="radio" name="dandiyaColor" value="#FF2D87" />
                <span class="color-swatch"></span>
              </label>
              <label class="color-chip" style="--c: #00FF66;" title="Lime Green">
                <input type="radio" name="dandiyaColor" value="#00FF66" />
                <span class="color-swatch"></span>
              </label>
            </div>
          </div>

          <button type="submit" class="submit-join-btn">
            <span>સર્કલ માં જોડાઓ Step Into The Circle</span>
            <span class="btn-shine"></span>
          </button>
        </form>
      </div>
    `;

    document.body.appendChild(this.el);

    this.el.querySelector('.modal-backdrop').addEventListener('click', () => this.close());
    this.el.querySelector('#join-close').addEventListener('click', () => this.close());

    this.el.querySelector('#join-form').addEventListener('submit', (e) => {
      e.preventDefault();
      const form = e.target;
      const name = form.querySelector('#dancer-name').value.trim() || 'Khelaiya';
      const gender = form.querySelector('input[name="gender"]:checked').value;
      const clothTheme = form.querySelector('input[name="clothColor"]:checked').value;
      const dandiyaColor = form.querySelector('input[name="dandiyaColor"]:checked').value;

      this.close();

      // Confetti celebration
      confetti({
        particleCount: 100,
        spread: 70,
        origin: { y: 0.6 }
      });

      if (this.onJoinSuccess) {
        this.onJoinSuccess({ name, gender, clothTheme, dandiyaColor });
      }
    });
  }

  open() {
    this.isOpen = true;
    this.el.classList.add('show');
    this.el.setAttribute('aria-hidden', 'false');
    setTimeout(() => this.el.querySelector('#dancer-name').focus(), 150);
  }

  close() {
    this.isOpen = false;
    this.el.classList.remove('show');
    this.el.setAttribute('aria-hidden', 'true');
  }
}
